import raw from '@/data/blog-posts.json';

/**
 * Loader for the growth agent's published articles.
 *
 * The dataset is generated by `tools/pipeline/build_blog.py` from the growth
 * agent's Markdown output. Committing it keeps the blog dependency-free at build
 * time and means the content the agent produces is actually served, indexed and
 * linkable rather than stranded in a git-ignored output directory.
 */
export type BlogPost = {
  slug: string;
  title: string;
  topic: string;
  locale: string;
  created_at: string;
  excerpt: string;
  body: string;
};

type Data = { generated_at: string; posts: BlogPost[] };

const data = raw as unknown as Data;

export const allPosts = data.posts;
export const blogGeneratedAt = data.generated_at;

export function getPost(slug: string): BlogPost | undefined {
  return data.posts.find((p) => p.slug === slug);
}
